// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY, LogFile} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public {
        c = new PENNY_BY_PENNY();
        LogFile log = new LogFile();
        c.SetLogFile(address(log));
        c.SetMinSum(0);
        c.Initialized();
    }
    function testFuzz_property(address actor, uint amount, uint lockTime) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 100 ether);
        lockTime = bound(lockTime, 0, 365 days);
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Put{value: amount}(lockTime) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}
